from pathlib import Pathimport numpy as npimport matplotlib.pyplot as pltfrom astropy.io import fitsfp = Path("/Users/carmencardenas/Desktop/TIC262530407S-ct20190818_1170.fits")with fits.open(fp) as hdul:    for hdu in hdul:        if hdu.data is None:            continue        if not hasattr(hdu, "columns") or hdu.columns is None:            continue        cols = [c.name for c in hdu.columns]        cols_lower = [c.lower() for c in cols]        # wavelength column        w_idx = next((i for i, c in enumerate(cols_lower) if "wave" in c or "lam" in c), None)        # flux column        f_idx = next((i for i, c in enumerate(cols_lower) if "flux" in c or c in ("f", "spec", "spectrum") or "count" in c), None)        if w_idx is None or f_idx is None:            continue        wcol = cols[w_idx]        fcol = cols[f_idx]        wave = np.array(hdu.data[wcol], dtype=float)        flux = np.array(hdu.data[fcol], dtype=float)        m = np.isfinite(wave) & np.isfinite(flux)        wave, flux = wave[m], flux[m]        plt.plot(wave, flux)        plt.xlabel(wcol)        plt.ylabel(fcol)        plt.title(fp.name)        plt.tight_layout()        plt.show()        break    else:        raise RuntimeError("Could not find wavelength+flux columns in any FITS table HDU.")